import json
import argparse
import datetime
from pathlib import Path
import re

# ==============================================================================
# BSF Metrics Calculator (Pure Math & I/O)
# ARCHITECTURE RULE: This script MUST NOT make any LLM API calls.
# It strictly calculates scores based on `matches.json` generated by Judge Subagents.
# ==============================================================================

def get_weight(val):
    if isinstance(val, (int, float)): return val
    v = str(val).upper()
    if v == "CORE": return 10
    if v == "HIGH": return 8
    if v == "MEDIUM": return 5
    if v == "LOW": return 2
    try: return float(val)
    except: return 1.0

def calculate_scores(matches_data: dict, outdir: Path) -> dict:
    """Calculate Recall, Precision, Usability, Artifact Size, and BPC."""
    gt_concepts = matches_data.get("ground_truth_concepts", [])
    extracted_concepts = matches_data.get("extracted_concepts", [])
    usability = matches_data.get("artifact_usability", {})

    mappings = matches_data.get("mappings", [])
    matched_gt_ids = set(m.get("gt_id") for m in mappings)
    matched_extracted_ids = set(m.get("extracted_id") for m in mappings)

    # 1. Knowledge Recall
    matched_weight = sum(get_weight(item.get("importance", item.get("weight", 0))) for item in gt_concepts if item.get("id") in matched_gt_ids)
    total_weight = sum(get_weight(item.get("importance", item.get("weight", 0))) for item in gt_concepts)
    recall = matched_weight / total_weight if total_weight > 0 else 0.0

    # 2. Dedup Precision & DAG Topology State Mutation Check
    valid_extracted_count = 0
    for item in extracted_concepts:
        if item.get("id") not in matched_extracted_ids or item.get("is_redundant"):
            continue
            
        inputs = item.get("inputs") or []
        outputs = item.get("outputs") or []
        
        # Ensure they are lists (handle explicit nulls) and elements are hashable
        if not isinstance(inputs, list): inputs = [inputs]
        if not isinstance(outputs, list): outputs = [outputs]
        
        try:
            if not outputs or set(inputs) == set(outputs):
                continue
        except TypeError:
            # If elements are unhashable (e.g. dicts), fallback to string comparison
            if not outputs or str(inputs) == str(outputs):
                continue
            
        valid_extracted_count += 1
        
    total_extracted = len(extracted_concepts)
    precision = valid_extracted_count / total_extracted if total_extracted > 0 else 0.0

    # ---------------------------------------------------------
    # FIX: NP-Hard Graphify Dimension Reduction (Flattened Tuples O(N) Mapping)
    # ---------------------------------------------------------
    gt_edges = matches_data.get("ground_truth_edges", [])
    extracted_edges = matches_data.get("extracted_edges", [])
    edge_mappings = matches_data.get("edge_mappings", [])
    
    # O(N) single-pass mapping of flattened tuples
    matched_gt_edge_ids = set(m.get("gt_id") for m in edge_mappings)
    matched_extracted_edge_ids = set(m.get("extracted_id") for m in edge_mappings)
    
    if gt_edges or extracted_edges:
        matched_edge_weight = sum(get_weight(item.get("importance", item.get("weight", 0))) for item in gt_edges if item.get("id") in matched_gt_edge_ids)
        total_edge_weight = sum(get_weight(item.get("importance", item.get("weight", 0))) for item in gt_edges)
        edge_recall = matched_edge_weight / total_edge_weight if total_edge_weight > 0 else 0.0
        
        valid_extracted_edge_count = sum(1 for item in extracted_edges if item.get("id") in matched_extracted_edge_ids and not item.get("is_redundant"))
        total_extracted_edges = len(extracted_edges)
        edge_precision = valid_extracted_edge_count / total_extracted_edges if total_extracted_edges > 0 else 0.0
        
        recall = (recall + edge_recall) / 2.0 if total_weight > 0 else edge_recall
        precision = (precision + edge_precision) / 2.0 if total_extracted > 0 else edge_precision

    # 3. Artifact Usability (Percentage)
    if isinstance(usability, (int, float)):
        usability_pct = float(usability)
    elif isinstance(usability, dict) and "score" in usability:
        usability_pct = float(usability["score"])
    else:
        scores = [
            usability.get("formatting_score", 0),
            usability.get("clarity_score", 0),
            usability.get("logical_score", 0)
        ]
        usability_pct = (sum(scores) / len(scores)) if scores else 0.0
        
    if usability_pct > 1.0:
        usability_pct /= 100.0
        
    usability_pct = max(0.0, min(1.0, usability_pct))

    # 4. Artifact Size (bytes)
    artifact_size = 0
    if outdir and outdir.exists():
        for f in outdir.iterdir():
            if f.is_file() and f.name not in ["matches.json", "scores_table.md", "evaluation_results.jsonl"]:
                artifact_size += f.stat().st_size

    # 5. Boolean Parameter Coverage (BPC)
    total_pairs = 0
    total_clauses = 0
    gt_text_map = {item.get("id"): item.get("text", item.get("description", "")) for item in gt_concepts}
    
    for mapping in mappings:
        semantic_pairs = mapping.get("semantic_pairs", [])
        total_pairs += len(semantic_pairs)
        
        gt_id = mapping.get("gt_id")
        gt_text = gt_text_map.get(gt_id, "")
        
        if not isinstance(gt_text, str):
            gt_text = str(gt_text) if gt_text else ""
            
        clauses = re.split(r'[,;，；]', gt_text)
        total_clauses += sum(1 for c in clauses if c.strip())
        
    bpc = (total_pairs / total_clauses) if total_clauses > 0 else 0.0

    return {
        "knowledge_recall": recall,
        "dedup_precision": precision,
        "artifact_usability": usability_pct,
        "artifact_size_bytes": artifact_size,
        "bpc": bpc
    }

def generate_markdown_report(book_id: str, scores: dict, out_file: Path):
    """Writes the calculated scores into a Markdown table."""
    md_content = f"""# 评测成绩单 (Evaluation Report)

**测试书目**: {book_id}

| 评测指标 (Metric) | 得分 (Score) | 描述 (Description) |
| --- | --- | --- |
| 知识召回率 (Knowledge Recall) | {scores['knowledge_recall']:.2%} | 核心心法提取覆盖率 |
| 去重准确率 (Dedup Precision) | {scores['dedup_precision']:.2%} | 有效且不重复提取占比 |
| 伪影可用性 (Artifact Usability) | {scores['artifact_usability']:.2%} | 生成档案的排版逻辑评分 |
| 产物大小 (Artifact Size) | {scores['artifact_size_bytes']} Bytes | 最终生成的 Skill/Graph 文件大小 |
| BPC (Boolean Parameter Coverage) | {scores.get('bpc', 0):.2f} | 语义配对/中文子句密度比率 (防剪枝) |

> 注：本报告由 Python `calculate_metrics.py` 根据 `matches.json` 自动生成。
"""
    out_file.write_text(md_content, encoding="utf-8")
    print(f"[OK] 成绩单已生成: {out_file}")

def main():
    parser = argparse.ArgumentParser(description="BSF Metrics Calculator (Pure Math)")
    parser.add_argument("--book", required=True, help="Book ID")
    parser.add_argument("--recipe", required=True, help="Recipe Name (e.g. Graphify Only, Cangjie Only, Parallel Hybrid)")
    parser.add_argument("--matches", required=True, help="Path to matches.json")
    parser.add_argument("--outdir", required=True, help="Path to output directory")
    
    args = parser.parse_args()
    
    matches_path = Path(args.matches)
    outdir = Path(args.outdir)
    
    if not matches_path.exists():
        print(f"[ERROR] 找不到输入文件 {matches_path}")
        return
        
    try:
        with open(matches_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        
        # DEFENSIVE PATCH: Handle LLM returning bare list instead of dict schema
        if isinstance(data, list):
            print("[WARN] LLM returned a bare list instead of dict. Auto-wrapping data to prevent crash.")
            data = {"mappings": data, "ground_truth_concepts": [], "extracted_concepts": []}
    except Exception as e:
        print(f"[ERROR] 解析 JSON 失败: {e}")
        return
        
    scores = calculate_scores(data, outdir)
    
    outdir.mkdir(parents=True, exist_ok=True)
    report_file = outdir / "scores_table.md"
    generate_markdown_report(args.book, scores, report_file)
    
    # Save to JSONL database
    db_file = outdir.parent / "evaluation_results.jsonl"
    record = {
        "timestamp": datetime.datetime.now().isoformat(),
        "book_id": args.book,
        "recipe": args.recipe,
        "recall": scores['knowledge_recall'],
        "precision": scores['dedup_precision'],
        "usability": scores['artifact_usability'],
        "artifact_size_bytes": scores['artifact_size_bytes'],
        "bpc": scores.get('bpc', 0)
    }
    with open(db_file, "a", encoding="utf-8") as f:
        f.write(json.dumps(record, ensure_ascii=False) + "\n")
    print(f"[OK] 记录已追加至数据库: {db_file}")

    print("=== 最终得分 ===")
    print(f"Recall: {scores['knowledge_recall']:.2%}")
    print(f"Precision: {scores['dedup_precision']:.2%}")
    print(f"Usability: {scores['artifact_usability']:.2%}")
    print(f"Artifact Size: {scores['artifact_size_bytes']} Bytes")
    print(f"BPC: {scores.get('bpc', 0):.2f}")

if __name__ == "__main__":
    main()
